private String getSensorError() {
    BiometricManager biometricManager = BiometricManager.from(mReactContext);
    // Check BIOMETRIC_STRONG (fingerprint / 3D face)
    int strongResult = biometricManager.canAuthenticate(
        BiometricManager.Authenticators.BIOMETRIC_STRONG
    );
    if (strongResult == BiometricManager.BIOMETRIC_SUCCESS) {
        return null;
    }
    // Also check BIOMETRIC_WEAK (Class-2 face on devices like Samsung, Pixel)
    // Note: OPPO/VIVO/Xiaomi proprietary 2D face is BIOMETRIC_CONVENIENCE (Class 1)
    // and is NOT accessible to apps via BiometricPrompt — it is screen-unlock only.
    // canAuthenticate(BIOMETRIC_WEAK) will return NONE_ENROLLED on those devices.
    int weakResult = biometricManager.canAuthenticate(
        BiometricManager.Authenticators.BIOMETRIC_WEAK
    );
    if (weakResult == BiometricManager.BIOMETRIC_SUCCESS) {
        return null;
    }
    if (strongResult == BiometricManager.BIOMETRIC_ERROR_NO_HARDWARE
            && weakResult == BiometricManager.BIOMETRIC_ERROR_NO_HARDWARE) {
        return "FingerprintScannerNotSupported";
    } else if (strongResult == BiometricManager.BIOMETRIC_ERROR_NONE_ENROLLED
            || weakResult == BiometricManager.BIOMETRIC_ERROR_NONE_ENROLLED) {
        return "FingerprintScannerNotEnrolled";
    } else if (strongResult == BiometricManager.BIOMETRIC_ERROR_HW_UNAVAILABLE) {
        return "FingerprintScannerNotAvailable";
    }
    return null;
}

